@sig trait Dispatch_Notice_Derivation_Api {
  def id: Art.BridgeId
  def dispatch_resolution_Id : Art.PortId
  def dispatch_status_Id : Art.PortId
  def shipping_confirmation_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var dispatch_status: Factory_Dispatch_Coordinator.Dispatch_Status.Type = $

  def put_dispatch_status(value : Factory_Dispatch_Coordinator.Dispatch_Status.Type) : Unit = {
    Contract(
      Modifies(dispatch_status),
      Ensures(
        dispatch_status == value
      )
    )
    Spec {
      dispatch_status = value
    }

    Art.putValue(dispatch_status_Id, Factory_Dispatch_Coordinator.Dispatch_Status_Payload(value))
  }

  // Logika spec var representing port state for outgoing data port
  @spec var shipping_confirmation: Factory_Dispatch_Coordinator.Shipping_Confirmation.Type = $

  def put_shipping_confirmation(value : Factory_Dispatch_Coordinator.Shipping_Confirmation.Type) : Unit = {
    Contract(
      Modifies(shipping_confirmation),
      Ensures(
        shipping_confirmation == value
      )
    )
    Spec {
      shipping_confirmation = value
    }

    Art.putValue(shipping_confirmation_Id, Factory_Dispatch_Coordinator.Shipping_Confirmation_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class Dispatch_Notice_Derivation_Initialization_Api (
  val id: Art.BridgeId,
  val dispatch_resolution_Id : Art.PortId,
  val dispatch_status_Id : Art.PortId,
  val shipping_confirmation_Id : Art.PortId) extends Dispatch_Notice_Derivation_Api

@datatype class Dispatch_Notice_Derivation_Operational_Api (
  val id: Art.BridgeId,
  val dispatch_resolution_Id : Art.PortId,
  val dispatch_status_Id : Art.PortId,
  val shipping_confirmation_Id : Art.PortId) extends Dispatch_Notice_Derivation_Api {

  // Logika spec var representing port state for incoming data port
  @spec var dispatch_resolution: Factory_Dispatch_Coordinator.Dispatch_Resolution = $

  def get_dispatch_resolution() : Option[Factory_Dispatch_Coordinator.Dispatch_Resolution] = {
    Contract(
      Ensures(
        Res == Some(dispatch_resolution)
      )
    )
    val value : Option[Factory_Dispatch_Coordinator.Dispatch_Resolution] = Art.getValue(dispatch_resolution_Id) match {
      case Some(Factory_Dispatch_Coordinator.Dispatch_Resolution_Payload(v)) => Some(v)
